from pathlib import Path
import base64, subprocess, tempfile, os

patch = base64.b64decode("""""").decode("utf-8")
with tempfile.NamedTemporaryFile("w", encoding="utf-8", delete=False) as f:
    f.write(patch)
    patch_path=f.name
try:
    subprocess.run(["patch","-p1","--forward","--batch","-i",patch_path], check=True)
finally:
    os.unlink(patch_path)

source=Path("index.html").read_text(encoding="utf-8")
for marker in ['data-build="ma-project-v89"','scrollIntoView','mobile inline editor, no bottom sheet']:
    if marker not in source:
        raise SystemExit(f"missing v89 marker: {marker}")
if 'document.body.classList.add("mobileContextSheetOpen")' in source:
    raise SystemExit("bottom-sheet open behavior still present")
